"""Nebius-AgentX Streamlit console. Run with: streamlit run app/main.py"""

from __future__ import annotations

import asyncio
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

import altair as alt  # noqa: E402
import pandas as pd  # noqa: E402
import streamlit as st  # noqa: E402

from src.config import get_settings  # noqa: E402
from src.diffing import collapse_rows, render_side_by_side_html, side_by_side  # noqa: E402
from src.models import AuditReport, FileResult  # noqa: E402
from src.orchestrator import AuditOrchestrator  # noqa: E402
from src.repo import combined_patch  # noqa: E402

EXAMPLE = ROOT / "examples" / "vulnerable_app.py"
SEVERITY_ORDER = ["Critical", "High", "Medium", "Low"]
SEVERITY_COLORS = {"Critical": "#ff4d5e", "High": "#ff8a3d", "Medium": "#f5c04a", "Low": "#6fb3ff"}

st.set_page_config(page_title="Nebius-AgentX", layout="wide")

st.markdown(
    """
<style>
:root { --nv-green:#76b900; --panel:#151b23; --line:#263040; --muted:#8b98a9; }
.block-container { padding-top: 2rem; max-width: 1400px; }
.hero h1 { font-size: 2.4rem; margin: 0; letter-spacing: -0.02em; }
.hero h1 span { color: var(--nv-green); }
.hero p { color: var(--muted); margin: .25rem 0 0; font-size: 1.05rem; }
.pill { display:inline-block; padding:2px 10px; border-radius:999px; font-size:.78rem; font-weight:600;
        border:1px solid var(--line); margin-right:6px; }
.pill.ok { color:#b8f07a; border-color:#3d5c12; background:#18240a; }
.pill.off { color:#f5c04a; border-color:#5c4a12; background:#241d0a; }
.check { display:inline-block; margin:2px 6px 2px 0; padding:2px 8px; border-radius:6px; font-size:.8rem;
         background:var(--panel); border:1px solid var(--line); }
.check.pass { color:#b8f07a; } .check.fail { color:#ff8a8a; }
.diff-wrap { max-height: 520px; overflow:auto; border:1px solid var(--line); border-radius:8px; }
table.diff { width:100%; border-collapse:collapse; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
             font-size:12.5px; table-layout:fixed; }
table.diff th { position:sticky; top:0; background:#10151c; color:var(--muted); text-align:left; padding:6px 8px;
                font-weight:600; border-bottom:1px solid var(--line); }
table.diff td { padding:1px 8px; vertical-align:top; white-space:pre-wrap; word-break:break-all; }
table.diff td.no, table.diff th.no { width:44px; color:#5d6b7c; text-align:right; user-select:none; }
table.diff td.del { background:rgba(255,77,94,.14); }
table.diff td.add { background:rgba(118,185,0,.16); }
table.diff tr.skip td { color:var(--muted); background:#10151c; text-align:center; font-style:italic; padding:4px; }
</style>
""",
    unsafe_allow_html=True,
)

settings = get_settings()


def load_example() -> None:
    st.session_state["code"] = EXAMPLE.read_text(encoding="utf-8")
    st.session_state["filename"] = "vulnerable_app.py"
    st.session_state["input_mode"] = "Paste code"


# ---------------------------------------------------------------- sidebar
with st.sidebar:
    st.markdown("### Inference")
    if settings.offline:
        st.markdown('<span class="pill off">Offline rule engine</span>', unsafe_allow_html=True)
        st.caption("Set NEBIUS_API_KEY in .env to add NVIDIA model reasoning on Nebius AI Cloud.")
    else:
        st.markdown('<span class="pill ok">Nebius AI Cloud connected</span>', unsafe_allow_html=True)
        st.caption(f"Endpoint: {settings.base_url}")
    st.markdown("**Model chain**")
    for i, m in enumerate(settings.model_chain):
        st.caption(f"{'Primary' if i == 0 else f'Fallback {i}'}: `{m}`")
    st.divider()
    st.markdown("### Agent loop")
    use_llm = st.toggle("Use Nebius models", value=not settings.offline, disabled=settings.offline)
    iterations = st.slider("Refactor/Review passes", 1, 4, 2)
    threshold = st.slider("Approval confidence", 0.5, 0.95, 0.8, 0.05)

# ---------------------------------------------------------------- input
st.markdown(
    '<div class="hero"><h1>Nebius-<span>AgentX</span></h1>'
    "<p>Three agents scan your code, write patches and verify them, on NVIDIA models served by Nebius AI Cloud.</p></div>",
    unsafe_allow_html=True,
)
st.write("")

mode = st.radio("Audit from", ["Repository or path", "Paste code"], horizontal=True, key="input_mode")
if mode == "Repository or path":
    source = st.text_input(
        "Local path or Git URL",
        placeholder="https://github.com/owner/repo  or  C:\\projects\\my-service",
        key="source",
    )
    filename = None
else:
    cols = st.columns([3, 1])
    st.session_state.setdefault("filename", "snippet.py")
    filename = cols[0].text_input("File name", key="filename")
    cols[1].write("")
    cols[1].button("Load vulnerable example", on_click=load_example, use_container_width=True)
    source = st.text_area("Code", height=280, key="code", placeholder="Paste a file to audit")

run = st.button("Run Nebius Agent Audit", type="primary", use_container_width=True)

EVENT_TEXT = {
    "start": lambda d: f"Auditing {d['files']} file(s) in **{d['mode']}** mode",
    "scan_done": lambda d: f"Scanner · `{d['file']}` · {d['findings']} finding(s)",
    "refactor": lambda d: f"Refactor · `{d['file']}` · pass {d['iteration']}",
    "review": lambda d: f"Reviewer · `{d['file']}` · confidence {d['confidence']:.0%} → {d['verdict']}",
    "error": lambda d: f"Error · `{d['file']}` · {d['error']}",
}

if run:
    if not (source or "").strip():
        st.warning("Enter a path, a Git URL or some code first.")
    else:
        with st.status("Agents working…", expanded=True) as status:
            def on_progress(event: str, data: dict) -> None:
                fmt = EVENT_TEXT.get(event)
                if fmt:
                    status.write(fmt(data))

            orchestrator = AuditOrchestrator(
                max_iterations=iterations, approve_threshold=threshold, use_llm=use_llm, progress=on_progress
            )
            try:
                report = asyncio.run(orchestrator.audit(source, filename=filename, snippet=mode == "Paste code"))
            except Exception as exc:  # show any failure in the UI instead of a traceback
                status.update(label="Audit failed", state="error")
                st.error(f"{type(exc).__name__}: {exc}")
                st.stop()
            status.update(label=f"Audit complete in {report.duration_s:.1f}s", state="complete", expanded=False)
        st.session_state["report"] = report


# ---------------------------------------------------------------- results
def checks_html(result: FileResult) -> str:
    if not result.review:
        return ""
    names = {
        "diff_applies": "Diff applies", "syntax_valid": "Syntax valid", "public_api_preserved": "API preserved",
        "minimal_change": "Minimal change", "no_new_issues": "No new issues", "findings_resolved": "All findings resolved",
    }
    return "".join(
        f'<span class="check {"pass" if ok else "fail"}">{"✓" if ok else "✗"} {names.get(k, k)}</span>'
        for k, ok in result.review.checks.items()
    )


def render(report: AuditReport) -> None:
    counts = report.severity_counts
    c = st.columns(5)
    c[0].metric("Files scanned", report.files_scanned)
    c[1].metric("Findings", report.total_findings)
    c[2].metric("Critical + High", counts["Critical"] + counts["High"])
    c[3].metric("Files patched", report.patched_files)
    c[4].metric("Avg. confidence", f"{report.average_confidence:.0%}" if report.average_confidence is not None else "—")
    st.caption(
        f"Mode: {report.mode} · Models: {', '.join(report.models_used) or 'rule engine only'} · "
        f"Source: {report.source}"
    )

    if not report.findings:
        st.success("No findings. The code passed every rule and model check.")
        return

    df = pd.DataFrame(
        [
            {"Severity": f.severity.value, "Category": f.category.value, "File": f.file, "Line": f.line,
             "Rule": f.rule_id, "Title": f.title, "CWE": f.cwe or "", "Detected by": f.source}
            for f in report.findings
        ]
    )
    left, right = st.columns([3, 2])
    with left:
        st.markdown("#### Severity distribution")
        sev = pd.DataFrame({"Severity": SEVERITY_ORDER, "Findings": [counts[s] for s in SEVERITY_ORDER]})
        chart = (
            alt.Chart(sev)
            .mark_bar(cornerRadiusTopRight=4, cornerRadiusBottomRight=4)
            .encode(
                y=alt.Y("Severity:N", sort=SEVERITY_ORDER, title=None),
                x=alt.X("Findings:Q", title=None, axis=alt.Axis(tickMinStep=1)),
                color=alt.Color("Severity:N", scale=alt.Scale(domain=list(SEVERITY_COLORS), range=list(SEVERITY_COLORS.values())), legend=None),
                tooltip=["Severity", "Findings"],
            )
            .properties(height=220)
        )
        st.altair_chart(chart, use_container_width=True)
    with right:
        st.markdown("#### By category")
        cat = df.groupby("Category").size().reset_index(name="Findings")
        donut = (
            alt.Chart(cat)
            .mark_arc(innerRadius=55)
            .encode(
                theta="Findings:Q",
                color=alt.Color("Category:N", scale=alt.Scale(scheme="tableau10"), legend=alt.Legend(orient="right")),
                tooltip=["Category", "Findings"],
            )
            .properties(height=220)
        )
        st.altair_chart(donut, use_container_width=True)

    st.markdown("#### Findings")
    df["_rank"] = df["Severity"].map({s: i for i, s in enumerate(SEVERITY_ORDER)})
    st.dataframe(df.sort_values(["_rank", "File", "Line"]).drop(columns="_rank"), hide_index=True, use_container_width=True)

    st.markdown("#### Patches")
    for result in report.results:
        if not result.findings:
            continue
        conf = f"{result.review.confidence:.0%} · {result.review.verdict}" if result.review else "no patch"
        with st.expander(f"{result.file} — {len(result.findings)} finding(s) — {conf}", expanded=result is report.results[0]):
            if result.error:
                st.error(result.error)
            if result.patch:
                st.markdown(checks_html(result), unsafe_allow_html=True)
                if result.patch.explanation:
                    st.caption(result.patch.explanation)
                rows = collapse_rows(side_by_side(result.patch.original, result.patch.patched), context=3)
                st.markdown(render_side_by_side_html(rows), unsafe_allow_html=True)
                st.download_button(
                    "Download patch", result.patch.diff, file_name=f"{Path(result.file).name}.patch",
                    key=f"dl-{result.file}",
                )
            else:
                st.info("No automatic patch for this file. See the recommendations in the findings table.")
            if result.review and result.review.notes:
                st.markdown("**Reviewer notes**")
                for note in result.review.notes:
                    st.markdown(f"- {note}")
            for note in result.notes:
                st.caption(note)

    st.divider()
    d1, d2 = st.columns(2)
    d1.download_button("Download full report (JSON)", report.model_dump_json(indent=2), "agentx-report.json",
                       use_container_width=True)
    d2.download_button("Download combined patch", combined_patch(report) or "", "agentx.patch",
                       use_container_width=True, disabled=not report.patched_files)


if "report" in st.session_state:
    render(st.session_state["report"])

"""A deliberately insecure inventory service used to demo Nebius-AgentX. Do not deploy."""

import asyncio
import hashlib
import os
import pickle
import sqlite3
import subprocess
import time

import requests
import yaml
from flask import Flask, request

app = Flask(__name__)
DB_PASSWORD = "hunter2-prod-db"
API_TOKEN = "demo-token-1234567890"


def get_db():
    return sqlite3.connect("inventory.db")


def find_item(name):
    conn = get_db()
    query = f"SELECT id, name, qty FROM items WHERE name = '{name}'"
    return conn.execute(f"SELECT id, name, qty FROM items WHERE name = '{name}'").fetchall()


def load_config(path):
    with open(path) as fh:
        return yaml.load(fh)


def restore_session(blob):
    return pickle.loads(blob)


def hash_password(password):
    return hashlib.md5(password.encode()).hexdigest()


def backup(target_dir):
    return subprocess.run("tar czf backup.tgz " + target_dir, shell=True)


def ping(host):
    return os.system("ping -c 1 " + host)


def calculate(expression):
    return eval(expression)


def add_tag(item, tags=[]):
    tags.append(item)
    return tags


def total_quantity(items):
    total = 0
    for i in range(len(items)):
        total += items[i]["qty"]
    return total


def fetch_price(sku):
    try:
        return requests.get(f"https://prices.example.com/{sku}", verify=False).json()
    except:
        return None


async def refresh_prices(skus):
    results = []
    for sku in skus:
        results.append(requests.get(f"https://prices.example.com/{sku}").json())
        time.sleep(0.5)
    return results


@app.route("/search")
def search():
    return {"items": find_item(request.args.get("q", ""))}


if __name__ == "__main__":
    app.run(host="0.0.0.0", debug=True)

"""The three collaborating agents: Scanner, Refactor and Reviewer.

Each agent works without a model (static rules, rule-based fixes, automated checks) and adds
Nebius-hosted NVIDIA model reasoning on top when an LLM client is supplied.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any, Protocol, Sequence

from .diffing import apply_unified_diff, diff_stats, unified_diff
from .fixers import FixResult, apply_rule_fixes
from .models import Category, CodeChunk, Finding, Patch, Review, Severity, SourceFile
from .nebius_client import ChatResult, NebiusError, extract_code_blocks, parse_json_payload, strip_reasoning
from .scanner import chunk_source, compare_findings, static_scan


class LLM(Protocol):
    available: bool

    async def chat(self, messages: Sequence[dict[str, str]], **kwargs: Any) -> ChatResult: ...

    async def chat_json(self, messages: Sequence[dict[str, str]], **kwargs: Any) -> Any: ...


LANG_ALIASES = {
    "python": {"python", "py", "python3"},
    "javascript": {"javascript", "js", "jsx", "node"},
    "typescript": {"typescript", "ts", "tsx"},
}
_CWE = re.compile(r"CWE-\d+", re.I)


def number_lines(text: str, start: int = 1) -> str:
    lines = text.splitlines()
    width = len(str(start + len(lines)))
    return "\n".join(f"{i:>{width}} | {line}" for i, line in enumerate(lines, start))


_PARSE_ERRORS = (SyntaxError, ValueError, RecursionError, MemoryError)


def public_names(code: str) -> set[str] | None:
    try:
        tree = ast.parse(code)
    except _PARSE_ERRORS:
        return None
    return {
        n.name for n in tree.body
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and not n.name.startswith("_")
    }


def is_valid_code(code: str, language: str) -> bool:
    if not code.strip():
        return False
    if language == "python":
        try:
            ast.parse(code)
        except _PARSE_ERRORS:
            return False
    return True


def _norm(text: str) -> str:
    return " ".join(text.split())


def _finding_line(f: Finding) -> str:
    return f"- [{f.id}] line {f.line} · {f.severity.value} · {f.title}: {f.recommendation or f.description}"


# ---------------------------------------------------------------- Scanner

SCANNER_SYSTEM = (
    "You are the Scanner agent in Nebius-AgentX, an autonomous security and performance auditor. "
    "Report only concrete, exploitable or measurable problems that you can tie to a specific line. "
    "Skip style preferences. Reply with JSON only."
)


class ScannerAgent:
    """Finds security flaws and performance bottlenecks with static rules plus model review."""

    def __init__(self, llm: LLM | None = None, *, chunk_lines: int = 120, max_llm_findings: int = 8) -> None:
        self.llm = llm
        self.chunk_lines = chunk_lines
        self.max_llm_findings = max_llm_findings

    def messages(self, chunk: CodeChunk, known: list[Finding]) -> list[dict[str, str]]:
        already = [f"line {f.line}: {f.title}" for f in known if chunk.start_line <= f.line <= chunk.end_line]
        user = (
            f"File: {chunk.file} ({chunk.language}), lines {chunk.start_line}-{chunk.end_line}.\n"
            f"Static analysis already reported: {'; '.join(already) if already else 'nothing'}. Do not repeat those.\n\n"
            'Return {"findings": [{"line": <int>, "title": <str>, "severity": "Low|Medium|High|Critical", '
            '"category": "Security|Performance|Reliability|Maintainability", "cwe": "CWE-<n> or null", '
            '"description": <str>, "recommendation": <str>}]}. Return {"findings": []} if the code is fine.\n\n'
            f"Code (line numbers on the left):\n{number_lines(chunk.content, chunk.start_line)}"
        )
        return [{"role": "system", "content": SCANNER_SYSTEM}, {"role": "user", "content": user}]

    def parse(self, payload: Any, chunk: CodeChunk, lines: list[str], known: list[Finding]) -> list[Finding]:
        if isinstance(payload, dict):
            items = payload.get("findings", [])
        elif isinstance(payload, list):
            items = payload
        else:
            items = []
        out: list[Finding] = []
        for n, item in enumerate(items[: self.max_llm_findings] if isinstance(items, list) else []):
            if not isinstance(item, dict):
                continue
            try:
                line = int(item.get("line"))
            except (TypeError, ValueError):
                continue
            title = str(item.get("title") or "").strip()
            if not title or not chunk.start_line <= line <= chunk.end_line:
                continue
            category = Category.parse(item.get("category"))
            if any(abs(f.line - line) <= 1 and f.category == category for f in [*known, *out]):
                continue
            cwe = _CWE.search(str(item.get("cwe") or ""))
            rule_id = f"LLM-{category.value[:4].upper()}"
            out.append(Finding(
                id=f"{rule_id}@{chunk.file}:{line}:{n}",
                file=chunk.file,
                line=line,
                rule_id=rule_id,
                title=title[:120],
                description=str(item.get("description") or "").strip()[:600],
                severity=Severity.parse(item.get("severity")),
                category=category,
                cwe=cwe.group(0).upper() if cwe else None,
                snippet=lines[line - 1].strip()[:240] if line <= len(lines) else "",
                recommendation=str(item.get("recommendation") or "").strip()[:600],
                source="llm",
            ))
        return out

    async def run(self, file: SourceFile) -> tuple[list[Finding], list[str]]:
        findings = static_scan(file)
        notes: list[str] = []
        if self.llm is not None:
            lines = file.content.splitlines()
            for chunk in chunk_source(file, max_lines=self.chunk_lines, overlap=10):
                try:
                    payload = await self.llm.chat_json(self.messages(chunk, findings), temperature=0.1, max_tokens=1800)
                except (NebiusError, ValueError) as exc:
                    notes.append(f"Scanner model call failed for lines {chunk.start_line}-{chunk.end_line}: {exc}")
                    continue
                findings.extend(self.parse(payload, chunk, lines, findings))
        findings.sort(key=lambda f: (-f.severity.rank, f.line, f.rule_id))
        return findings, notes


# ---------------------------------------------------------------- Refactor

REFACTOR_SYSTEM = (
    "You are the Refactor agent in Nebius-AgentX. Fix the listed security and performance findings with "
    "minimal, behavior-preserving edits. Keep public function and class names and signatures unless a "
    "finding requires a change. Add type hints to code you touch. Do not add placeholder comments or "
    "explanations inside the code."
)


class RefactorAgent:
    """Writes the patch: deterministic rule fixes first, then model edits for the rest."""

    def __init__(self, llm: LLM | None = None, *, max_lines: int = 800) -> None:
        self.llm = llm
        self.max_lines = max_lines

    def messages(self, file: SourceFile, findings: list[Finding], code: str, feedback: str | None) -> list[dict[str, str]]:
        fence = file.language if file.language != "text" else ""
        parts = [
            f"Fix these findings in {file.path}:",
            "\n".join(_finding_line(f) for f in findings),
            "",
            "The code below already includes deterministic fixes from the rule engine. Keep them.",
        ]
        if feedback:
            parts += ["", "Reviewer feedback on your previous attempt:", feedback]
        parts += [
            "",
            f"Reply with the complete updated file in one ```{fence} code block, followed by a ```json block: "
            '{"addressed": ["finding ids you fixed"], "explanation": "one short paragraph"}.',
            "",
            f"```{fence}\n{code}\n```",
        ]
        return [{"role": "system", "content": REFACTOR_SYSTEM}, {"role": "user", "content": "\n".join(parts)}]

    @staticmethod
    def parse(text: str, language: str) -> tuple[str | None, dict[str, Any]]:
        blocks = extract_code_blocks(strip_reasoning(text))
        aliases = LANG_ALIASES.get(language, {language})
        code: str | None = None
        meta: Any = {}
        for lang, body in blocks:
            if lang == "json":
                try:
                    meta = parse_json_payload(body)
                except ValueError:
                    meta = {}
            elif code is None and (lang in aliases or lang == ""):
                code = body
        if code is None:
            others = [body for lang, body in blocks if lang != "json"]
            code = max(others, key=len) if others else None
        return code, meta if isinstance(meta, dict) else {}

    def _budget(self, code: str) -> int:
        return int(min(8192, max(1024, len(code) / 3 * 1.6 + 600)))

    async def run(
        self, file: SourceFile, findings: list[Finding], feedback: str | None = None
    ) -> tuple[Patch | None, list[str]]:
        if not findings:
            return None, []
        fix = apply_rule_fixes(file.content, findings) if file.language == "python" else FixResult(file.content)
        notes = list(fix.notes)
        code = fix.code
        ids = {f.id for f in findings}
        addressed = set(fix.addressed)
        explanation: list[str] = []
        if fix.addressed:
            explanation.append(f"Rule engine fixed {len(fix.addressed)} finding(s) deterministically.")
        used_llm = False
        remaining = [f for f in findings if f.id not in addressed]
        if self.llm is not None and (remaining or feedback) and file.content.count("\n") <= self.max_lines:
            try:
                result = await self.llm.chat(
                    self.messages(file, findings, code, feedback), temperature=0.15, max_tokens=self._budget(code)
                )
                llm_code, meta = self.parse(result.content, file.language)
                lost = set()
                if llm_code and file.language == "python":
                    before, after = public_names(file.content), public_names(llm_code)
                    lost = (before - after) if before is not None and after is not None else set()
                if lost:
                    notes.append("Refactor model dropped public names (" + ", ".join(sorted(lost)) + "); kept the rule-engine patch.")
                elif llm_code and is_valid_code(llm_code, file.language):
                    if file.content.endswith("\n") and not llm_code.endswith("\n"):
                        llm_code += "\n"
                    code = llm_code
                    used_llm = True
                    claimed = meta.get("addressed", [])
                    addressed |= {str(i) for i in claimed if str(i) in ids} if isinstance(claimed, list) else set()
                    if meta.get("explanation"):
                        explanation.append(str(meta["explanation"]).strip())
                else:
                    notes.append("Refactor model returned no valid code; kept the rule-engine patch.")
            except NebiusError as exc:
                notes.append(f"Refactor model call failed: {exc}")
        elif self.llm is not None and remaining:
            notes.append(f"File is longer than {self.max_lines} lines; only rule-engine fixes were applied.")
        if code == file.content:
            return None, notes
        stats = diff_stats(file.content, code)
        source = "rules+llm" if used_llm and fix.addressed else ("llm" if used_llm else "rules")
        patch = Patch(
            file=file.path,
            original=file.content,
            patched=code,
            diff=unified_diff(file.content, code, file.path),
            addressed=sorted(addressed),
            explanation=" ".join(explanation),
            source=source,
            added=int(stats["added"]),
            removed=int(stats["removed"]),
        )
        return patch, notes


# ---------------------------------------------------------------- Reviewer

REVIEWER_SYSTEM = (
    "You are the Reviewer agent in Nebius-AgentX. Check whether a proposed patch fixes the listed findings "
    "without changing intended behavior or adding new risk. Be strict. Reply with JSON only."
)


class ReviewerAgent:
    """Verifies a patch with automated checks and, when available, a model review; outputs a confidence score."""

    def __init__(self, llm: LLM | None = None, *, approve_threshold: float = 0.8, revise_threshold: float = 0.5) -> None:
        self.llm = llm
        self.approve_threshold = approve_threshold
        self.revise_threshold = revise_threshold

    def automated_checks(self, file: SourceFile, findings: list[Finding], patch: Patch) -> tuple[dict[str, bool], list[str], list[str], list[Finding]]:
        checks: dict[str, bool] = {}
        try:
            rebuilt = apply_unified_diff(file.content, patch.diff)
            checks["diff_applies"] = rebuilt.rstrip("\r\n") == patch.patched.rstrip("\r\n")
        except ValueError:
            checks["diff_applies"] = False
        checks["syntax_valid"] = is_valid_code(patch.patched, file.language)
        if file.language == "python":
            before, after = public_names(file.content), public_names(patch.patched)
            checks["public_api_preserved"] = before is None or (after is not None and before <= after)
        checks["minimal_change"] = diff_stats(file.content, patch.patched)["changed_ratio"] <= 0.6

        after_findings = static_scan(SourceFile(path=file.path, language=file.language, content=patch.patched))
        resolved, unresolved, new = compare_findings(findings, after_findings)
        for f in findings:
            if f.source == "llm":
                (resolved if f.id in patch.addressed else unresolved).append(f.id)
        checks["no_new_issues"] = not new
        checks["findings_resolved"] = not unresolved
        return checks, resolved, unresolved, new

    def heuristic_confidence(self, checks: dict[str, bool], resolved: list[str], findings: list[Finding]) -> float:
        """Half structural checks, half severity-weighted share of findings resolved."""
        if not checks.get("diff_applies", True) or not checks.get("syntax_valid", True):
            return 0.0
        structural = [v for k, v in checks.items() if k != "findings_resolved"]
        total = sum(f.severity.rank for f in findings)
        done = sum(f.severity.rank for f in findings if f.id in resolved)
        resolved_ratio = done / total if total else 1.0
        return round(0.5 * resolved_ratio + 0.5 * (sum(structural) / len(structural)), 3)

    def messages(self, findings: list[Finding], patch: Patch, checks: dict[str, bool]) -> list[dict[str, str]]:
        diff = patch.diff if len(patch.diff) <= 12000 else patch.diff[:12000] + "\n... (diff truncated)"
        user = (
            f"File: {patch.file}\nFindings to fix:\n" + "\n".join(_finding_line(f) for f in findings) +
            f"\n\nAutomated checks: {json.dumps(checks)}\n\nPatch:\n```diff\n{diff}\n```\n\n"
            'Return {"confidence": <0.0-1.0>, "verdict": "approve|revise|reject", '
            '"unresolved": ["finding ids still present"], "notes": ["short, actionable feedback"]}.'
        )
        return [{"role": "system", "content": REVIEWER_SYSTEM}, {"role": "user", "content": user}]

    def verdict(self, confidence: float) -> str:
        if confidence >= self.approve_threshold:
            return "approve"
        return "revise" if confidence >= self.revise_threshold else "reject"

    async def run(self, file: SourceFile, findings: list[Finding], patch: Patch) -> Review:
        checks, resolved, unresolved, new = self.automated_checks(file, findings, patch)
        confidence = self.heuristic_confidence(checks, resolved, findings)
        notes: list[str] = []
        if new:
            notes.append("Patch introduced: " + "; ".join(f"line {f.line} {f.title}" for f in new))
        failed = [k for k, v in checks.items() if not v and k != "findings_resolved"]
        if failed:
            notes.append("Failed checks: " + ", ".join(failed))
        if self.llm is not None and confidence > 0:
            try:
                payload = await self.llm.chat_json(self.messages(findings, patch, checks), temperature=0.0, max_tokens=900)
                if isinstance(payload, dict):
                    llm_conf = float(payload.get("confidence", confidence))
                    llm_conf = min(1.0, max(0.0, llm_conf))
                    confidence = round(0.55 * confidence + 0.45 * llm_conf, 3)
                    ids = {f.id for f in findings}
                    extra = [str(i) for i in payload.get("unresolved", []) or [] if str(i) in ids]
                    for i in extra:
                        if i in resolved:
                            resolved.remove(i)
                        if i not in unresolved:
                            unresolved.append(i)
                    notes += [str(n).strip() for n in payload.get("notes", []) or [] if str(n).strip()][:6]
            except (NebiusError, ValueError, TypeError) as exc:
                notes.append(f"Reviewer model call failed, used automated checks only: {exc}")
        checks["findings_resolved"] = not unresolved
        verdict = self.verdict(confidence)
        critical_left = [f for f in findings if f.id in unresolved and f.severity is Severity.CRITICAL]
        if verdict == "approve" and critical_left:
            verdict = "revise"
            notes.append("Not approved: Critical finding still open: " + "; ".join(f"line {f.line} {f.title}" for f in critical_left))
        gates = [k for k in ("diff_applies", "syntax_valid", "public_api_preserved", "no_new_issues") if checks.get(k) is False]
        if verdict == "approve" and gates:
            verdict = "revise"
            notes.append("Not approved: failed hard check(s): " + ", ".join(gates))
        return Review(
            file=patch.file,
            confidence=confidence,
            verdict=verdict,  # type: ignore[arg-type]
            checks=checks,
            resolved=resolved,
            unresolved=unresolved,
            new_findings=new,
            notes=notes,
        )

"""FastAPI service exposing the audit pipeline. Run with: uvicorn src.api:app --reload"""

from __future__ import annotations

from fastapi import FastAPI, HTTPException
from fastapi.responses import PlainTextResponse
from pydantic import BaseModel, Field

from . import __version__
from .config import get_settings
from .models import AuditReport
from .orchestrator import AuditOrchestrator
from .repo import combined_patch

app = FastAPI(
    title="Nebius-AgentX",
    version=__version__,
    description="Autonomous multi-agent code refactoring and security audit on Nebius AI Cloud with NVIDIA models.",
)


class AuditRequest(BaseModel):
    source: str | None = Field(None, description="Local path or Git URL to audit")
    code: str | None = Field(None, description="Raw code to audit instead of a path")
    filename: str | None = Field(None, description="File name for raw code, e.g. app.py")
    max_iterations: int = Field(2, ge=1, le=5)
    approve_threshold: float = Field(0.8, ge=0.0, le=1.0)
    use_llm: bool = True


@app.get("/health")
async def health() -> dict[str, object]:
    s = get_settings()
    return {"status": "ok", "version": __version__, "mode": "offline" if s.offline else "nebius", "models": list(s.model_chain)}


async def _run(req: AuditRequest) -> AuditReport:
    if not (req.code or req.source):
        raise HTTPException(status_code=422, detail="Provide either `source` (path or Git URL) or `code`.")
    orchestrator = AuditOrchestrator(
        max_iterations=req.max_iterations, approve_threshold=req.approve_threshold, use_llm=req.use_llm
    )
    try:
        if req.code:
            return await orchestrator.audit(req.code, filename=req.filename, snippet=True)
        return await orchestrator.audit(req.source or "")
    except (FileNotFoundError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc


@app.post("/audit", response_model=AuditReport)
async def audit(req: AuditRequest) -> AuditReport:
    return await _run(req)


@app.post("/audit/patch", response_class=PlainTextResponse)
async def audit_patch(req: AuditRequest) -> str:
    """Same audit, returned as a single unified diff ready for `git apply`."""
    return combined_patch(await _run(req))

"""Runtime configuration read from environment variables and an optional .env file."""

from __future__ import annotations

import os
from dataclasses import dataclass

from dotenv import load_dotenv

DEFAULT_BASE_URL = "https://api.tokenfactory.nebius.com/v1/"
DEFAULT_MODEL = "nvidia/Llama-3_1-Nemotron-Ultra-253B-v1"
DEFAULT_FALLBACKS = "nvidia/Llama-3_3-Nemotron-Super-49B-v1,meta-llama/Llama-3.3-70B-Instruct"


def _int(name: str, default: int) -> int:
    try:
        return int(os.getenv(name, str(default)))
    except ValueError:
        return default


def _float(name: str, default: float) -> float:
    try:
        return float(os.getenv(name, str(default)))
    except ValueError:
        return default


@dataclass(frozen=True)
class Settings:
    api_key: str | None = None
    base_url: str = DEFAULT_BASE_URL
    model: str = DEFAULT_MODEL
    fallback_models: tuple[str, ...] = ()
    timeout_s: float = 120.0
    max_retries: int = 3
    max_concurrency: int = 4
    github_token: str | None = None

    @property
    def offline(self) -> bool:
        return not self.api_key

    @property
    def model_chain(self) -> tuple[str, ...]:
        chain: list[str] = []
        for name in (self.model, *self.fallback_models):
            if name and name not in chain:
                chain.append(name)
        return tuple(chain)


def get_settings() -> Settings:
    load_dotenv(override=False)
    key = os.getenv("NEBIUS_API_KEY", "").strip() or None
    if key and key.lower().startswith(("your", "<")):
        key = None
    fallbacks = tuple(
        m.strip() for m in os.getenv("NEBIUS_FALLBACK_MODELS", DEFAULT_FALLBACKS).split(",") if m.strip()
    )
    return Settings(
        api_key=key,
        base_url=os.getenv("NEBIUS_BASE_URL", DEFAULT_BASE_URL).strip() or DEFAULT_BASE_URL,
        model=os.getenv("NVIDIA_MODEL_NAME", DEFAULT_MODEL).strip() or DEFAULT_MODEL,
        fallback_models=fallbacks,
        timeout_s=_float("NEBIUS_TIMEOUT_SECONDS", 120.0),
        max_retries=max(0, _int("NEBIUS_MAX_RETRIES", 3)),
        max_concurrency=max(1, _int("AGENTX_MAX_CONCURRENCY", 4)),
        github_token=os.getenv("GITHUB_TOKEN", "").strip() or None,
    )

"""Unified and side-by-side diffs, a strict diff applier used for verification, and HTML rendering."""

from __future__ import annotations

import difflib
import html
import re
from dataclasses import dataclass

_HUNK = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")


def _lines(text: str) -> list[str]:
    lines = text.splitlines(keepends=True)
    if lines and not lines[-1].endswith(("\n", "\r")):
        lines[-1] += "\n"
    return lines


def unified_diff(original: str, patched: str, path: str = "file", context: int = 3) -> str:
    """A git-style unified diff. Returns an empty string when the texts are identical."""
    if original == patched:
        return ""
    return "".join(
        difflib.unified_diff(_lines(original), _lines(patched), fromfile=f"a/{path}", tofile=f"b/{path}", n=context)
    )


def apply_unified_diff(original: str, diff: str) -> str:
    """Apply a single-file unified diff, raising ValueError if any context line does not match."""
    src = _lines(original)
    out: list[str] = []
    i = 0
    lines = diff.splitlines(keepends=True)
    k = 0
    while k < len(lines):
        m = _HUNK.match(lines[k])
        if not m:
            k += 1
            continue
        start = int(m.group(1))
        count = int(m.group(2)) if m.group(2) is not None else 1
        target = start - 1 if count > 0 else start
        if target < i:
            raise ValueError("Overlapping hunks")
        out.extend(src[i:target])
        i = target
        k += 1
        while k < len(lines) and not lines[k].startswith("@@"):
            line = lines[k]
            tag, body = line[:1], line[1:]
            if tag in (" ", "-"):
                if i >= len(src) or src[i].rstrip("\r\n") != body.rstrip("\r\n"):
                    raise ValueError(f"Context mismatch at original line {i + 1}")
                if tag == " ":
                    out.append(src[i])
                i += 1
            elif tag == "+":
                out.append(body if body.endswith("\n") else body + "\n")
            elif tag == "\\" or line.strip() == "":
                pass
            else:
                raise ValueError(f"Unexpected diff line: {line!r}")
            k += 1
    out.extend(src[i:])
    return "".join(out)


@dataclass
class DiffRow:
    kind: str  # equal | replace | delete | insert | skip
    left_no: int | None
    left: str
    right_no: int | None
    right: str


def side_by_side(original: str, patched: str) -> list[DiffRow]:
    a, b = original.splitlines(), patched.splitlines()
    rows: list[DiffRow] = []
    matcher = difflib.SequenceMatcher(a=a, b=b, autojunk=False)
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            for x in range(i2 - i1):
                rows.append(DiffRow("equal", i1 + x + 1, a[i1 + x], j1 + x + 1, b[j1 + x]))
            continue
        for x in range(max(i2 - i1, j2 - j1)):
            li = i1 + x if i1 + x < i2 else None
            rj = j1 + x if j1 + x < j2 else None
            kind = "replace" if li is not None and rj is not None else ("delete" if li is not None else "insert")
            rows.append(DiffRow(
                kind,
                li + 1 if li is not None else None,
                a[li] if li is not None else "",
                rj + 1 if rj is not None else None,
                b[rj] if rj is not None else "",
            ))
    return rows


def collapse_rows(rows: list[DiffRow], context: int = 3) -> list[DiffRow]:
    """Keep changed rows plus `context` rows around them; replace long equal runs with a skip row."""
    changed = [i for i, r in enumerate(rows) if r.kind != "equal"]
    if not changed:
        return rows
    keep = set()
    for i in changed:
        keep.update(range(max(0, i - context), min(len(rows), i + context + 1)))
    out: list[DiffRow] = []
    skipped = 0
    for i, row in enumerate(rows):
        if i in keep:
            if skipped:
                out.append(DiffRow("skip", None, f"{skipped} unchanged lines", None, ""))
                skipped = 0
            out.append(row)
        else:
            skipped += 1
    if skipped:
        out.append(DiffRow("skip", None, f"{skipped} unchanged lines", None, ""))
    return out


def diff_stats(original: str, patched: str) -> dict[str, float]:
    a, b = original.splitlines(), patched.splitlines()
    added = removed = 0
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(a=a, b=b, autojunk=False).get_opcodes():
        if tag in ("replace", "delete"):
            removed += i2 - i1
        if tag in ("replace", "insert"):
            added += j2 - j1
    return {"added": added, "removed": removed, "changed_ratio": round((added + removed) / max(1, len(a) + len(b)), 4)}


def render_side_by_side_html(rows: list[DiffRow]) -> str:
    """Render rows as a two-column HTML table (styles live in the Streamlit app)."""
    parts = ['<div class="diff-wrap"><table class="diff"><thead><tr>'
             '<th class="no"></th><th>Original</th><th class="no"></th><th>AgentX patch</th></tr></thead><tbody>']
    for r in rows:
        if r.kind == "skip":
            parts.append(f'<tr class="skip"><td colspan="4">{html.escape(r.left)}</td></tr>')
            continue
        left_cls = "del" if r.kind in ("replace", "delete") else ""
        right_cls = "add" if r.kind in ("replace", "insert") else ""
        parts.append(
            "<tr>"
            f'<td class="no">{r.left_no or ""}</td><td class="code {left_cls}">{html.escape(r.left) or "&nbsp;"}</td>'
            f'<td class="no">{r.right_no or ""}</td><td class="code {right_cls}">{html.escape(r.right) or "&nbsp;"}</td>'
            "</tr>"
        )
    parts.append("</tbody></table></div>")
    return "".join(parts)

"""Deterministic, AST-guided fixes for the static rules the Scanner agent reports.

The Refactor agent applies these first, then asks the model to handle whatever is left, so
a patch exists even when Nebius is unreachable and the model starts from a safer baseline.
"""

from __future__ import annotations

import ast
import re
from dataclasses import dataclass, field

from .models import Finding, SourceFile
from .pyanalysis import ImportMap, is_secret_name, looks_like_secret
from .scanner import _is_mutable_default, call_name, compare_findings, is_const, secret_target, static_scan

FIXABLE = {"PY001", "PY002", "PY004", "PY005", "PY006", "PY008", "PY009", "PY010", "PY012", "PY014"}
_EXCEPT = re.compile(r"except\s*:")


@dataclass
class FixResult:
    code: str
    addressed: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    @property
    def changed(self) -> bool:
        return bool(self.addressed)


@dataclass
class _Edit:
    start: int
    end: int
    text: str
    ids: list[str] = field(default_factory=list)
    imports: set[str] = field(default_factory=set)


class _Source:
    """Maps ast (line, utf-8 byte column) positions to string offsets."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.lines = [line for line in re.split(r"(?<=\n)", text) if line]
        self.starts: list[int] = []
        pos = 0
        for line in self.lines:
            self.starts.append(pos)
            pos += len(line)

    def line_start(self, lineno: int) -> int:
        return self.starts[lineno - 1] if 0 < lineno <= len(self.starts) else len(self.text)

    def offset(self, lineno: int, col_bytes: int) -> int:
        if not 0 < lineno <= len(self.lines):
            return len(self.text)
        line = self.lines[lineno - 1]
        col = len(line.encode("utf-8")[:col_bytes].decode("utf-8", errors="ignore"))
        return self.starts[lineno - 1] + col

    def span(self, node: ast.AST) -> tuple[int, int]:
        return self.offset(node.lineno, node.col_offset), self.offset(node.end_lineno, node.end_col_offset)  # type: ignore[attr-defined]

    def segment(self, node: ast.AST) -> str:
        start, end = self.span(node)
        return self.text[start:end]


def ensure_imports(code: str, modules: set[str]) -> str:
    """Add `import x` lines for modules not already bound at module level."""
    if not modules:
        return code
    tree = ast.parse(code)
    bound: set[str] = set()
    insert_after = 0
    for i, node in enumerate(tree.body):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            insert_after = node.end_lineno or node.lineno
            if isinstance(node, ast.Import):
                bound.update(a.asname or a.name.split(".")[0] for a in node.names)
        elif i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
            insert_after = node.end_lineno or node.lineno
    missing = sorted(m for m in modules if m not in bound)
    if not missing:
        return code
    lines = [line for line in re.split(r"(?<=\n)", code) if line]
    if insert_after and not lines[insert_after - 1].endswith("\n"):
        lines[insert_after - 1] += "\n"
    lines.insert(insert_after, "".join(f"import {m}\n" for m in missing))
    return "".join(lines)


def _docstring(node: ast.stmt) -> bool:
    return isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str)


def apply_rule_fixes(source: str, findings: list[Finding]) -> FixResult:
    if source.startswith("﻿"):  # keep a byte-order mark but fix the code after it
        inner = apply_rule_fixes(source[1:], findings)
        return FixResult("﻿" + inner.code if inner.addressed else source, inner.addressed, inner.notes)
    wanted: dict[tuple[str, int], list[Finding]] = {}
    for f in findings:
        if f.source == "static" and f.rule_id in FIXABLE:
            wanted.setdefault((f.rule_id, f.line), []).append(f)
    if not wanted:
        return FixResult(source)
    try:
        tree = ast.parse(source)
    except (SyntaxError, ValueError, RecursionError, MemoryError):
        return FixResult(source, notes=["Rule engine skipped this file because it does not parse."])

    src = _Source(source)
    imports = ImportMap(tree)
    edits: list[_Edit] = []
    notes: list[str] = []

    def take(rule: str, line: int) -> list[str]:
        return [f.id for f in wanted.pop((rule, line), [])]

    def fix_call(node: ast.Call) -> None:
        name = imports.resolve(call_name(node.func))  # `from os import system` -> os.system
        kw = {k.arg: k for k in node.keywords if k.arg}
        line = node.lineno
        if ("PY008", line) in wanted:
            for k in node.keywords:
                if k.arg and is_secret_name(k.arg) and isinstance(k.value, ast.Constant) and looks_like_secret(k.value.value, 4):
                    env = re.sub(r"[^A-Za-z0-9]+", "_", k.arg).upper()
                    edits.append(_Edit(*src.span(k.value), f'os.environ.get("{env}", "")', take("PY008", line), {"os"}))
        if name == "hashlib.new" and ("PY005", line) in wanted and node.args and isinstance(node.args[0], ast.Constant):
            edits.append(_Edit(*src.span(node.args[0]), '"sha256"', take("PY005", line)))
        if ("PY001", line) in wanted:
            if name == "eval" and len(node.args) == 1 and not node.keywords:
                edits.append(_Edit(*src.span(node.func), "ast.literal_eval", take("PY001", line), {"ast"}))
            elif name == "exec":
                notes.append(f"Line {line}: exec() needs a manual redesign; left for the model.")
        constant_cmd = bool(node.args) and isinstance(node.args[0], ast.Constant)
        if ("PY002", line) in wanted and constant_cmd:
            notes.append(f"Line {line}: fixed shell command left as is; it takes no input and may rely on shell syntax.")
        elif ("PY002", line) in wanted:
            if name == "os.system" and len(node.args) == 1 and not node.keywords:
                arg = src.segment(node.args[0])
                edits.append(_Edit(*src.span(node), f"subprocess.run(shlex.split({arg}), check=False).returncode",
                                   take("PY002", line), {"subprocess", "shlex"}))
            elif name.startswith("subprocess.") and "shell" in kw:
                if node.args and not isinstance(node.args[0], (ast.List, ast.Tuple)):
                    edits.append(_Edit(*src.span(node.args[0]), f"shlex.split({src.segment(node.args[0])})", [], {"shlex"}))
                edits.append(_Edit(*src.span(kw["shell"].value), "False", take("PY002", line)))
        if name == "yaml.load" and ("PY004", line) in wanted and node.args:
            edits.append(_Edit(*src.span(node), f"yaml.safe_load({src.segment(node.args[0])})", take("PY004", line), {"yaml"}))
        if name in ("hashlib.md5", "hashlib.sha1") and ("PY005", line) in wanted:
            edits.append(_Edit(*src.span(node.func), "hashlib.sha256", take("PY005", line), {"hashlib"}))
        if "verify" in kw and ("PY006", line) in wanted and is_const(kw["verify"].value, False):
            edits.append(_Edit(*src.span(kw["verify"].value), "True", take("PY006", line)))
        if name.split(".")[-1] == "run" and "debug" in kw and ("PY014", line) in wanted:
            edits.append(_Edit(*src.span(kw["debug"].value), "False", take("PY014", line)))
        if name == "time.sleep" and ("PY012", line) in wanted:
            args = ", ".join(src.segment(a) for a in node.args)
            edits.append(_Edit(*src.span(node), f"await asyncio.sleep({args})", take("PY012", line), {"asyncio"}))

    def fix_defaults(fn: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        a = fn.args
        positional = [*a.posonlyargs, *a.args]
        pairs = list(zip(positional[len(positional) - len(a.defaults):], a.defaults))
        pairs += [(arg, d) for arg, d in zip(a.kwonlyargs, a.kw_defaults) if d is not None]
        targets = [(arg, d) for arg, d in pairs if ("PY010", d.lineno) in wanted and _is_mutable_default(d)]
        if not targets or not fn.body:
            return
        first = fn.body[0]
        if src.lines[first.lineno - 1][: first.col_offset].strip():
            notes.append(f"Line {fn.lineno}: one-line function; mutable default left for the model.")
            return
        if _docstring(first):
            insert_line = (first.end_lineno or first.lineno) + 1
            anchor = fn.body[1] if len(fn.body) > 1 else first
        else:
            insert_line, anchor = first.lineno, first
        indent = re.match(r"[ \t]*", src.lines[anchor.lineno - 1]).group(0)  # type: ignore[union-attr]
        unit = "\t" if indent.startswith("\t") else "    "
        block = "".join(f"{indent}if {arg.arg} is None:\n{indent}{unit}{arg.arg} = {src.segment(d)}\n" for arg, d in targets)
        pos = src.line_start(insert_line)
        if pos == len(source) and not source.endswith("\n"):
            block = "\n" + block
        for arg, d in targets:
            edits.append(_Edit(*src.span(d), "None", take("PY010", d.lineno)))
        edits.append(_Edit(pos, pos, block))

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            fix_call(node)
        elif isinstance(node, ast.ExceptHandler) and node.type is None and ("PY009", node.lineno) in wanted:
            start = src.offset(node.lineno, node.col_offset)
            m = _EXCEPT.match(source, start)
            if m:
                edits.append(_Edit(start, m.end(), "except Exception:", take("PY009", node.lineno)))
        elif isinstance(node, (ast.Assign, ast.AnnAssign)) and ("PY008", node.lineno) in wanted:
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            name = secret_target(targets, node.value)
            if name and node.value is not None:
                env = re.sub(r"[^A-Za-z0-9]+", "_", name).upper()
                edits.append(_Edit(*src.span(node.value), f'os.environ.get("{env}", "")', take("PY008", node.lineno), {"os"}))
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            fix_defaults(node)

    edits.sort(key=lambda e: (e.start, e.end), reverse=True)
    code = source
    addressed: list[str] = []
    imports: set[str] = set()
    floor = len(source) + 1
    for e in edits:
        if e.end > floor:
            notes.append("Skipped an overlapping fix; the model will handle it.")
            continue
        code = code[: e.start] + e.text + code[e.end :]
        floor = e.start
        addressed.extend(e.ids)
        imports |= e.imports
    if not addressed:
        return FixResult(source, notes=notes)
    try:
        code = ensure_imports(code, imports)
        ast.parse(code)
    except (SyntaxError, ValueError, RecursionError) as exc:
        return FixResult(source, notes=[*notes, f"Rule fixes produced invalid code ({exc}); discarded."])
    # Self-check: only claim findings whose rule actually stopped firing.
    after = static_scan(SourceFile(path="patched.py", language="python", content=code))
    _, still_open, _ = compare_findings([f for f in findings if f.source == "static"], after)
    claimed = sorted(set(addressed) - set(still_open))
    if len(claimed) < len(set(addressed)):
        notes.append("Some rule fixes reduced but did not remove a finding; left for the model to finish.")
    return FixResult(code, claimed, notes)

"""Typed data passed between the agents, the API and the UI."""

from __future__ import annotations

from datetime import datetime
from enum import Enum
from typing import Literal

from pydantic import BaseModel, Field, computed_field


class Severity(str, Enum):
    LOW = "Low"
    MEDIUM = "Medium"
    HIGH = "High"
    CRITICAL = "Critical"

    @property
    def rank(self) -> int:
        return {"Low": 1, "Medium": 2, "High": 3, "Critical": 4}[self.value]

    @classmethod
    def parse(cls, value: object) -> "Severity":
        text = str(value or "").strip().lower()
        mapping = {
            "info": cls.LOW, "informational": cls.LOW, "low": cls.LOW, "minor": cls.LOW,
            "medium": cls.MEDIUM, "moderate": cls.MEDIUM, "warning": cls.MEDIUM,
            "high": cls.HIGH, "major": cls.HIGH, "error": cls.HIGH,
            "critical": cls.CRITICAL, "severe": cls.CRITICAL, "blocker": cls.CRITICAL,
        }
        return mapping.get(text, cls.MEDIUM)


class Category(str, Enum):
    SECURITY = "Security"
    PERFORMANCE = "Performance"
    RELIABILITY = "Reliability"
    MAINTAINABILITY = "Maintainability"

    @classmethod
    def parse(cls, value: object) -> "Category":
        text = str(value or "").strip().lower()
        if text.startswith(("sec", "vuln")):
            return cls.SECURITY
        if text.startswith(("perf", "speed", "efficien")):
            return cls.PERFORMANCE
        if text.startswith(("maint", "style", "quality", "readab")):
            return cls.MAINTAINABILITY
        return cls.RELIABILITY


class SourceFile(BaseModel):
    path: str
    language: str
    content: str


class CodeChunk(BaseModel):
    file: str
    language: str
    start_line: int
    end_line: int
    content: str


class Finding(BaseModel):
    id: str
    file: str
    line: int
    rule_id: str
    title: str
    description: str = ""
    severity: Severity
    category: Category
    cwe: str | None = None
    snippet: str = ""
    recommendation: str = ""
    source: Literal["static", "llm"] = "static"


class Patch(BaseModel):
    file: str
    original: str
    patched: str
    diff: str
    addressed: list[str] = Field(default_factory=list)
    explanation: str = ""
    source: Literal["rules", "llm", "rules+llm"] = "rules"
    added: int = 0
    removed: int = 0


class Review(BaseModel):
    file: str
    confidence: float = Field(ge=0.0, le=1.0)
    verdict: Literal["approve", "revise", "reject"]
    checks: dict[str, bool] = Field(default_factory=dict)
    resolved: list[str] = Field(default_factory=list)
    unresolved: list[str] = Field(default_factory=list)
    new_findings: list[Finding] = Field(default_factory=list)
    notes: list[str] = Field(default_factory=list)


class FileResult(BaseModel):
    file: str
    language: str
    findings: list[Finding] = Field(default_factory=list)
    patch: Patch | None = None
    review: Review | None = None
    iterations: int = 0
    notes: list[str] = Field(default_factory=list)
    error: str | None = None


class AuditReport(BaseModel):
    source: str
    mode: Literal["nebius", "offline"]
    models_used: list[str] = Field(default_factory=list)
    started_at: datetime
    duration_s: float = 0.0
    files_scanned: int = 0
    results: list[FileResult] = Field(default_factory=list)

    @property
    def findings(self) -> list[Finding]:
        return [f for r in self.results for f in r.findings]

    @computed_field  # type: ignore[prop-decorator]
    @property
    def total_findings(self) -> int:
        return len(self.findings)

    @computed_field  # type: ignore[prop-decorator]
    @property
    def severity_counts(self) -> dict[str, int]:
        counts = {s.value: 0 for s in Severity}
        for f in self.findings:
            counts[f.severity.value] += 1
        return counts

    @computed_field  # type: ignore[prop-decorator]
    @property
    def patched_files(self) -> int:
        return sum(1 for r in self.results if r.patch is not None)

    @computed_field  # type: ignore[prop-decorator]
    @property
    def average_confidence(self) -> float | None:
        scores = [r.review.confidence for r in self.results if r.review is not None]
        return round(sum(scores) / len(scores), 3) if scores else None

"""Async client for NVIDIA models served on Nebius AI Cloud through its OpenAI-compatible API.

Adds what the agents need on top of the OpenAI SDK: retries with exponential backoff, a
fallback chain across models, a shared concurrency limit, streaming, reasoning-trace removal
and tolerant JSON parsing of model output.
"""

from __future__ import annotations

import asyncio
import json
import random
import re
import time
from dataclasses import dataclass
from typing import Any, AsyncIterator, Awaitable, Callable, Sequence

import openai
from openai import AsyncOpenAI

from .config import Settings, get_settings

Message = dict[str, str]

_THINK_RE = re.compile(r"<think>.*?</think>", re.DOTALL | re.IGNORECASE)
_FENCE_RE = re.compile(r"```(?P<lang>[\w+#.-]*)[ \t]*\r?\n(?P<body>.*?)```", re.DOTALL)

_RETRYABLE: tuple[type[Exception], ...] = (
    openai.RateLimitError,
    openai.APITimeoutError,
    openai.APIConnectionError,
    openai.InternalServerError,
)
_TRY_NEXT_MODEL: tuple[type[Exception], ...] = (openai.NotFoundError, openai.UnprocessableEntityError)


class NebiusError(RuntimeError):
    """Raised when no configured model could serve a request."""


@dataclass
class ChatResult:
    content: str
    model: str
    latency_s: float
    prompt_tokens: int = 0
    completion_tokens: int = 0


def strip_reasoning(text: str | None) -> str:
    """Remove <think>…</think> traces that Nemotron reasoning models can emit."""
    cleaned = _THINK_RE.sub("", text or "")
    lower = cleaned.lower()
    if "<think>" in lower:  # an unterminated trace means the answer was cut off inside it
        cleaned = cleaned[: lower.index("<think>")]
    return cleaned.strip()


def extract_code_blocks(text: str) -> list[tuple[str, str]]:
    return [(m.group("lang").lower(), m.group("body")) for m in _FENCE_RE.finditer(text or "")]


def _first_json_span(text: str) -> str | None:
    for i, ch in enumerate(text):
        if ch not in "{[":
            continue
        depth, in_str, escaped = 0, False, False
        for j in range(i, len(text)):
            c = text[j]
            if in_str:
                if escaped:
                    escaped = False
                elif c == "\\":
                    escaped = True
                elif c == '"':
                    in_str = False
                continue
            if c == '"':
                in_str = True
            elif c in "{[":
                depth += 1
            elif c in "}]":
                depth -= 1
                if depth == 0:
                    candidate = text[i : j + 1]
                    try:
                        json.loads(candidate)
                        return candidate
                    except ValueError:
                        break
    return None


def parse_json_payload(text: str) -> Any:
    """Parse JSON from a model reply that may include reasoning, prose or code fences."""
    cleaned = strip_reasoning(text)
    candidates = [cleaned] + [body for lang, body in extract_code_blocks(cleaned) if lang in ("json", "")]
    for candidate in candidates:
        try:
            return json.loads(candidate.strip())
        except ValueError:
            continue
    span = _first_json_span(cleaned)
    if span is not None:
        return json.loads(span)
    raise ValueError("No JSON value found in model output")


class NebiusClient:
    """Chat client for Nebius AI Cloud with retries and NVIDIA model fallbacks."""

    def __init__(
        self,
        settings: Settings | None = None,
        *,
        client: Any | None = None,
        sleep: Callable[[float], Awaitable[None]] = asyncio.sleep,
    ) -> None:
        self.settings = settings or get_settings()
        if client is None and self.settings.api_key:
            client = AsyncOpenAI(
                api_key=self.settings.api_key,
                base_url=self.settings.base_url,
                timeout=self.settings.timeout_s,
                max_retries=0,
            )
        self._client = client
        self._sleep = sleep
        self._sem: asyncio.Semaphore | None = None
        self.models_used: list[str] = []
        self.calls = 0
        self.prompt_tokens = 0
        self.completion_tokens = 0

    @property
    def available(self) -> bool:
        return self._client is not None

    @property
    def models(self) -> list[str]:
        return list(self.settings.model_chain)

    def _semaphore(self) -> asyncio.Semaphore:
        if self._sem is None:
            self._sem = asyncio.Semaphore(self.settings.max_concurrency)
        return self._sem

    def _backoff(self, attempt: int) -> float:
        return min(8.0, 0.5 * 2**attempt) + random.uniform(0, 0.25)

    def _note_model(self, name: str) -> None:
        if name not in self.models_used:
            self.models_used.append(name)

    def _require_client(self) -> Any:
        if self._client is None:
            raise NebiusError("NEBIUS_API_KEY is not configured, so Nebius inference is unavailable.")
        return self._client

    async def chat(
        self,
        messages: Sequence[Message],
        *,
        model: str | None = None,
        temperature: float = 0.2,
        max_tokens: int = 2048,
        json_mode: bool = False,
    ) -> ChatResult:
        client = self._require_client()
        errors: list[str] = []
        for name in [model] if model else self.models:
            use_json = json_mode
            attempt = 0
            while True:
                kwargs: dict[str, Any] = {
                    "model": name,
                    "messages": list(messages),
                    "temperature": temperature,
                    "max_tokens": max_tokens,
                }
                if use_json:
                    kwargs["response_format"] = {"type": "json_object"}
                start = time.perf_counter()
                try:
                    async with self._semaphore():
                        response = await client.chat.completions.create(**kwargs)
                except openai.AuthenticationError as exc:
                    raise NebiusError(f"Nebius rejected the API key: {exc}") from exc
                except _TRY_NEXT_MODEL as exc:
                    errors.append(f"{name}: {type(exc).__name__}")
                    break
                except openai.BadRequestError as exc:
                    if use_json:  # some models reject response_format; retry without it
                        use_json = False
                        continue
                    errors.append(f"{name}: {type(exc).__name__}")
                    break
                except _RETRYABLE as exc:
                    if attempt < self.settings.max_retries:
                        await self._sleep(self._backoff(attempt))
                        attempt += 1
                        continue
                    errors.append(f"{name}: {type(exc).__name__} after {attempt + 1} attempts")
                    break
                except openai.APIStatusError as exc:
                    errors.append(f"{name}: HTTP {exc.status_code}")
                    break
                return self._result(response, name, start)
        raise NebiusError("All Nebius models failed: " + "; ".join(errors))

    def _result(self, response: Any, name: str, start: float) -> ChatResult:
        choices = getattr(response, "choices", None) or []
        content = choices[0].message.content if choices else ""
        usage = getattr(response, "usage", None)
        prompt = int(getattr(usage, "prompt_tokens", 0) or 0)
        completion = int(getattr(usage, "completion_tokens", 0) or 0)
        used = getattr(response, "model", None) or name
        self.calls += 1
        self.prompt_tokens += prompt
        self.completion_tokens += completion
        self._note_model(used)
        return ChatResult(
            content=strip_reasoning(content),
            model=used,
            latency_s=round(time.perf_counter() - start, 3),
            prompt_tokens=prompt,
            completion_tokens=completion,
        )

    async def chat_json(self, messages: Sequence[Message], **kwargs: Any) -> Any:
        result = await self.chat(messages, json_mode=True, **kwargs)
        try:
            return parse_json_payload(result.content)
        except ValueError:
            repair = [
                *messages,
                {"role": "assistant", "content": result.content},
                {"role": "user", "content": "That reply was not valid JSON. Reply with only the JSON value."},
            ]
            retry = await self.chat(repair, json_mode=True, **kwargs)
            return parse_json_payload(retry.content)

    async def stream(
        self,
        messages: Sequence[Message],
        *,
        model: str | None = None,
        temperature: float = 0.2,
        max_tokens: int = 2048,
    ) -> AsyncIterator[str]:
        """Yield content deltas, falling back to the next model if one cannot start a stream."""
        client = self._require_client()
        errors: list[str] = []
        for name in [model] if model else self.models:
            try:
                stream = await client.chat.completions.create(
                    model=name,
                    messages=list(messages),
                    temperature=temperature,
                    max_tokens=max_tokens,
                    stream=True,
                )
            except openai.AuthenticationError as exc:
                raise NebiusError(f"Nebius rejected the API key: {exc}") from exc
            except (*_TRY_NEXT_MODEL, *_RETRYABLE, openai.BadRequestError, openai.APIStatusError) as exc:
                errors.append(f"{name}: {type(exc).__name__}")
                continue
            self._note_model(name)
            self.calls += 1
            async for chunk in stream:
                choices = getattr(chunk, "choices", None) or []
                if not choices:
                    continue
                delta = getattr(choices[0].delta, "content", None)
                if delta:
                    yield delta
            return
        raise NebiusError("All Nebius models failed to stream: " + "; ".join(errors))

"""Python static analysis: import resolution, lightweight taint tracking and the rule checks.

Taint tracking is intra-procedural and deliberately simple. Values from web requests
(`request.args`, `request.GET`, route parameters, ...) are "web" tainted; `input()` and
`sys.argv` are "local" tainted. Taint flows through assignments, string building, calls and
attribute access, and stops at sanitizers such as int(), escape() or secure_filename().
Path, redirect, SSRF and similar sinks only fire on web taint, so command-line tools that
open the file named on their command line are not flagged.
"""

from __future__ import annotations

import ast
import re
import stat
from typing import Iterator

from .models import Severity
from .rules import RULES

# ---------------------------------------------------------------- shared helpers


def call_name(func: ast.AST) -> str:
    """Dotted name of a call target as written, e.g. 'subprocess.run' or 'conn.execute'."""
    parts: list[str] = []
    while isinstance(func, ast.Attribute):
        parts.append(func.attr)
        func = func.value
    if isinstance(func, ast.Name):
        parts.append(func.id)
    return ".".join(reversed(parts))


def is_const(node: ast.AST | None, value: object) -> bool:
    return isinstance(node, ast.Constant) and node.value is value


def is_str(node: ast.AST | None) -> bool:
    return isinstance(node, ast.Constant) and isinstance(node.value, str)


def is_dynamic_string(node: ast.AST) -> bool:
    if isinstance(node, ast.JoinedStr):
        return any(isinstance(v, ast.FormattedValue) for v in node.values)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Mod, ast.Add)):
        return any(isinstance(side, (ast.Constant, ast.JoinedStr, ast.BinOp)) for side in (node.left, node.right))
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "format":
        return True
    return False


def is_mutable_default(node: ast.AST) -> bool:
    if isinstance(node, (ast.List, ast.Dict, ast.Set)):
        return True
    return isinstance(node, ast.Call) and call_name(node.func) in {"list", "dict", "set"} and not node.args


_SECRET_NAME = re.compile(
    r"(?:^|_)(?:password|passwd|pwd|secret|secret_key|api_key|apikey|access_key|private_key|"
    r"auth_token|access_token|token|credentials?|client_secret)$"
)
_SAFE_SECRET_VALUE = re.compile(r"^(?:changeme|example|placeholder|xxx+|\*+|<.*>|\$\{.*\}|test|none|null|todo)$", re.I)


def snake(name: str) -> str:
    return re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", name).lower()


def is_secret_name(name: str | None) -> bool:
    return bool(name) and bool(_SECRET_NAME.search(snake(name)))  # type: ignore[arg-type]


def looks_like_secret(value: object, min_len: int = 6) -> bool:
    if not isinstance(value, str):
        return False
    v = value.strip()
    return len(v) >= min_len and " " not in v and not _SAFE_SECRET_VALUE.match(v)


def _target_name(node: ast.AST) -> str | None:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Constant) and isinstance(node.slice.value, str):
        return node.slice.value  # e.g. request.form['password']
    return None


def high_entropy(value: str) -> bool:
    """Random-looking token: long, mixes letters and digits, no spaces or path/URL punctuation."""
    if len(value) < 20 or re.search(r"[\s/\\.:]", value):
        return False
    classes = sum(bool(re.search(p, value)) for p in (r"[a-z]", r"[A-Z]", r"\d"))
    return classes >= 3 or (classes == 2 and len(set(value)) >= 12 and re.search(r"\d", value) is not None)


def secret_target(targets: list[ast.AST], value: ast.AST | None) -> str | None:
    """Name of a secret-like target assigned a literal credential, else None."""
    if not (isinstance(value, ast.Constant) and looks_like_secret(value.value)):
        return None
    for t in targets:
        name = _target_name(t)
        if not name:
            continue
        last = snake(name).split("_")[-1]
        if is_secret_name(name) and last != value.value.lower():  # type: ignore[union-attr]
            return name
        if last in ("key", "keys") and high_entropy(value.value):  # type: ignore[arg-type]
            return name
    return None


def _names(target: ast.AST) -> list[str]:
    if isinstance(target, ast.Name):
        return [target.id]
    if isinstance(target, (ast.Tuple, ast.List)):
        return [n for elt in target.elts for n in _names(elt)]
    if isinstance(target, ast.Starred):
        return _names(target.value)
    return []


_SCOPE_TYPES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)
_BINDING_TYPES = (ast.Assign, ast.AnnAssign, ast.AugAssign, ast.For, ast.AsyncFor, ast.comprehension,
                  ast.withitem, ast.NamedExpr)


def index_scopes(tree: ast.AST) -> tuple[dict[ast.AST, list[ast.AST]], list[ast.AST]]:
    """One pass over the tree: nodes grouped by the function (or module) scope they belong to, plus imports."""
    scopes: dict[ast.AST, list[ast.AST]] = {tree: []}
    imports: list[ast.AST] = []
    stack = [(child, tree) for child in ast.iter_child_nodes(tree)]
    while stack:
        node, scope = stack.pop()
        scopes[scope].append(node)
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            imports.append(node)
        if isinstance(node, _SCOPE_TYPES):
            scopes[node] = []
            scope = node
        stack.extend((child, scope) for child in ast.iter_child_nodes(node))
    return scopes, imports


def scope_nodes(root: ast.AST) -> Iterator[ast.AST]:
    """Nodes in root's own scope, without descending into nested functions or lambdas."""
    stack = list(ast.iter_child_nodes(root))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            continue
        stack.extend(ast.iter_child_nodes(node))


# ---------------------------------------------------------------- import resolution

STAR_EXPORTS = {
    "Crypto.Cipher": {"AES", "DES", "DES3", "ARC2", "ARC4", "Blowfish", "CAST", "XOR"},
    "Cryptodome.Cipher": {"AES", "DES", "DES3", "ARC2", "ARC4", "Blowfish", "CAST"},
    "Crypto.Hash": {"MD2", "MD4", "MD5", "SHA", "SHA1"},
    "flask": {"request", "redirect", "render_template_string", "make_response", "send_file", "Markup"},
    "os": {"system", "popen", "remove", "unlink", "chmod"},
    "subprocess": {"call", "run", "Popen", "check_call", "check_output", "getoutput"},
    "pickle": {"load", "loads"},
}


class ImportMap:
    """Maps local names to the fully qualified names they were imported as."""

    def __init__(self, tree: ast.AST, import_nodes: list[ast.AST] | None = None) -> None:
        self.aliases: dict[str, str] = {}
        self.star: list[str] = []
        self.modules: set[str] = set()
        for node in import_nodes if import_nodes is not None else ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    self.modules.add(a.name.split(".")[0])
                    if a.asname:
                        self.aliases[a.asname] = a.name
                    else:
                        head = a.name.split(".")[0]
                        self.aliases.setdefault(head, head)
            elif isinstance(node, ast.ImportFrom) and node.module and not node.level:
                self.modules.add(node.module.split(".")[0])
                for a in node.names:
                    if a.name == "*":
                        self.star.append(node.module)
                    else:
                        self.aliases[a.asname or a.name] = f"{node.module}.{a.name}"

    def resolve(self, dotted: str) -> str:
        if not dotted:
            return ""
        head, _, rest = dotted.partition(".")
        base = self.aliases.get(head)
        if base is None:
            for mod in self.star:
                if head in STAR_EXPORTS.get(mod, ()):
                    base = f"{mod}.{head}"
                    break
        if base is None:
            return dotted
        return f"{base}.{rest}" if rest else base


